#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 1e5 + 5;

int n;
int f[N], c[N], cnt[N];
long long ans[N];

int main() {
    scanf("%d", &n);
    for (int i = 2; i <= n; i++) {
        scanf("%d", &f[i]);
        cnt[f[i]]++;
    }
    for (int i = 1; i <= n; i++)
        scanf("%d", &c[i]);
    for (int i = n; i >= 1; i--) {
        if (cnt[i] == 0)
            ans[i] = c[i];
        ans[i] = min(ans[i], 1ll * c[i]);
        ans[f[i]] += ans[i];
    }
    printf("%lld\n", ans[1]);
    return 0;
}

#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 505;
const int oo = 1e9 + 10;

int n, k;
int f[N * N];

int main() {
    scanf("%d%d", &n, &k);
    for (int i = 1; i < N * N; i++)
        f[i] = oo;
    int s = 0;
    for (int i = 1; i <= n; i++) {
        int a, c;
        scanf("%d%d", &a, &c);
        s += a;
        for (int j = s; j >= a; j--)
            f[j] = min(f[j], f[j - a] + c);
    }
    int ans = 0;
    for (int i = 0; i < N * N; i++)
        if (f[i] <= k)
            ans = i;
    printf("%d\n", ans);
    return 0;
}
